import { CatalogSection, StudentSchedule } from "./types";

const MON = 0;
const TUE = 1;
const WED = 2;
const THU = 3;
const FRI = 4;

const days = (...active: number[]): boolean[] => {
  const result = [false, false, false, false, false];
  for (const i of active) result[i] = true;
  return result;
};

/**
 * The student already has two sections on their schedule:
 *  - a MWF 10:00-11:00 lecture
 *  - a Tu/Th 14:00-15:00 discussion
 *
 * Any catalog section that meets on a shared day and overlaps either of
 * these time ranges is a conflict.
 */
export const STUDENT_SCHEDULE: StudentSchedule = {
  sections: [
    {
      id: "enrolled-1",
      meetings: [{ days: days(MON, WED, FRI), startTime: "10:00", endTime: "11:00" }],
    },
    {
      id: "enrolled-2",
      meetings: [{ days: days(TUE, THU), startTime: "14:00", endTime: "15:00" }],
    },
  ],
};

const TOTAL_SECTIONS = 40;

/**
 * 40 catalog sections, sorted by id -- this is the order the "server"
 * paginates over (see catalog.ts).
 *
 * Every 3rd section (id % 3 === 0) meets MWF 10:30-11:30, which overlaps
 * the student's MWF 10:00-11:00 lecture. Every other section meets
 * Tu/Th 08:00-09:00, which conflicts with nothing on the student's
 * schedule.
 *
 * That's 13 conflicting sections (ids 3, 6, 9, ..., 39) and 27
 * non-conflicting sections out of 40 total. Tests compute this ground
 * truth independently (by filtering this array directly) rather than
 * hard-coding "27" -- but it's worth knowing the numbers while reading
 * the fixture.
 */
export const CATALOG_SECTIONS: CatalogSection[] = Array.from(
  { length: TOTAL_SECTIONS },
  (_, index) => {
    const id = index + 1;
    const conflictsWithSchedule = id % 3 === 0;

    return {
      id: `sec-${String(id).padStart(3, "0")}`,
      courseNumber: `CS ${100 + id}`,
      sectionNumber: "001",
      meetings: [
        conflictsWithSchedule
          ? { days: days(MON, WED, FRI), startTime: "10:30", endTime: "11:30" }
          : { days: days(TUE, THU), startTime: "08:00", endTime: "09:00" },
      ],
    };
  }
);
